sql_query:
SELECT v.VAR_id
FROM varInfo v
WHERE v.gene_name = 'NEK1' AND v.HighImpact AND v.CADDphred > 20;

SELECT varInfo.VAR_id, CHROM, POS, ID, REF, ALT, QUAL, FILTER, AC, AN, AF, gene_name, HighImpact, ModerateImpact, Synonymous, CADDphred, PolyPhen, SIFT
FROM varInfo
WHERE gene_name = 'NEK1' AND HighImpact = 1 AND CADDphred > 20;

SELECT vi.VAR_id 
FROM varInfo vi 
WHERE vi.gene_name = 'NEK1' AND vi.HighImpact = 1 AND vi.CADDphred > 20;

SELECT v.VAR_id
FROM varInfo v
WHERE v.gene_name = 'NEK1' AND v.HighImpact = 1 AND v.CADDphred > 20;

SELECT COUNT(*) 
FROM varInfo 
WHERE gene_name = 'TARDBP' AND SIFT = 'deleterious';

SELECT COUNT(*) 
FROM varInfo 
WHERE gene_name = 'TARDBP' AND SIFT = 'deleterious';

SELECT COUNT(*) 
FROM varInfo 
WHERE gene_name = 'TARDBP' AND SIFT LIKE '%deleterious%';

SELECT AVG(AF) AS avg_AF
FROM varInfo
WHERE Synonymous = 1 OR ModerateImpact = 1 OR HighImpact = 1;

SELECT AVG(AF) AS avg_AF
FROM varInfo
WHERE Synonymous = 1 OR ModerateImpact = 1 OR HighImpact = 1;

SELECT AVG(AF) AS avg_AF 
FROM varInfo 
WHERE Synonymous = 1 OR ModerateImpact = 1 OR HighImpact = 1;

SELECT AVG(age) 
FROM pheno 
WHERE pheno = 'ALS';

SELECT AVG(age) 
FROM pheno 
WHERE pheno = 'ALS';

SELECT varInfo.VAR_id, varInfo.CHROM, varInfo.POS, varInfo.ID, varInfo.REF, varInfo.ALT, varInfo.QUAL, varInfo.FILTER, varInfo.AC, varInfo.AN, varInfo.AF, varInfo.gene_name, varInfo.HighImpact, varInfo.ModerateImpact, varInfo.Synonymous, varInfo.CADDphred, varInfo.PolyPhen, varInfo.SIFT
FROM varInfo
ORDER BY varInfo.CADDphred DESC, varInfo.AF DESC;

SELECT DISTINCT VAR_id 
FROM varInfo 
WHERE Synonymous = 1 AND HighImpact = 1;

SELECT DISTINCT v.VAR_id 
FROM varInfo v 
WHERE v.Synonymous = 1 AND v.HighImpact = 1;

SELECT AVG(AF) AS MAF
FROM varInfo
WHERE gene_name = 'TARDBP' AND ModerateImpact = 1;

SELECT AVG(AF) AS MAF
FROM varInfo
WHERE gene_name = 'TARDBP' AND ModerateImpact = 1;

SELECT AVG(AF) AS MAF
FROM varInfo
WHERE gene_name = 'TARDBP' AND ModerateImpact = 1;

SELECT AVG(AF) AS MAF
FROM varInfo
WHERE gene_name = 'TARDBP' AND ModerateImpact = 1;

SELECT DISTINCT VAR_id, gene_name
FROM varInfo_synthetic
WHERE HighImpact = 1 AND (ALS_1 = 2 OR ALS_2 = 2 OR ALS_3 = 2 OR ALS_4 = 2 OR ALS_5 = 2);

SELECT DISTINCT varInfo_synthetic.VAR_id, gene_name 
FROM varInfo_synthetic 
WHERE HighImpact = 'TRUE' AND (ALS_1 = 2 OR ALS_2 = 2 OR ALS_3 = 2 OR ALS_4 = 2 OR ALS_5 = 2);

SELECT SUM(CASE WHEN gene_name IS NOT NULL THEN 1 ELSE 0 END) AS total_burden
FROM varInfo_synthetic
WHERE VAR_id IN (
    SELECT VAR_id FROM varInfo_synthetic WHERE gene_name IS NOT NULL AND (ALS_1 = 1 OR ALS_2 = 1 OR ALS_3 = 1 OR ALS_4 = 1 OR ALS_5 = 1)
) - SUM(CASE WHEN gene_name IS NOT NULL THEN 1 ELSE 0 END) AS total_burden
FROM varInfo_synthetic
WHERE VAR_id IN (
    SELECT VAR_id FROM varInfo_synthetic WHERE gene_name IS NOT NULL AND (Control_1 = 1 OR Control_2 = 1 OR Control_3 = 1 OR Control_4 = 1 OR Control_5 = 1)
);

SELECT SUM(CASE WHEN ALS_1 = 'case' THEN 1 ELSE 0 END) AS case_count, 
       SUM(CASE WHEN Control_1 = 'control' THEN 1 ELSE 0 END) AS control_count
FROM varInfo_synthetic;

SELECT CHROM, POS, REF, ALT, gene_name, SUM(CASE WHEN ALS_1 = 'Carrier' THEN 1 ELSE 0 END) AS ALS_Carriers, SUM(CASE WHEN Control_1 = 'Carrier' THEN 1 ELSE 0 END) AS Control_Carriers
FROM varInfo_synthetic
GROUP BY CHROM, POS, REF, ALT, gene_name;

SELECT SUM(CASE WHEN VAR_id IN (SELECT VAR_id FROM varInfo_synthetic WHERE gene_name LIKE '%X%') THEN 1 ELSE 0 END) AS FemaleCarriers,
       SUM(CASE WHEN VAR_id IN (SELECT VAR_id FROM varInfo_synthetic WHERE gene_name LIKE '%Y%') THEN 1 ELSE 0 END) AS MaleCarriers
FROM varInfo_synthetic;

SELECT AVG(AF) AS MAF
FROM varInfo_synthetic
WHERE gene_name = 'TARDBP' AND ModerateImpact = 1;

SELECT AVG(AF) AS MAF
FROM varInfo_synthetic
WHERE gene_name = 'TARDBP' AND ModerateImpact = 1;

SELECT COUNT(*) 
FROM varInfo_synthetic 
WHERE gene_name = 'SOD1' AND ModerateImpact IS NOT NULL OR HighImpact IS NOT NULL;

SELECT COUNT(*) 
FROM varInfo_synthetic 
WHERE gene_name = 'SOD1' AND ALS_1 IN ('female', 'carrier') AND PolyPhen = 'pathogenic';
